export default function createBehavior(api) {
  const widget = 'steam-relay-lab'
  const namespace = 'miniforge-relay-lab-v1'
  const lobbyName = 'Miniforge Relay Lab'
  const cloudFile = 'miniforge-relay-lab-probe.json'
  const pingEvent = namespace + ':ping'
  const pongEvent = namespace + ':pong'
  let panel
  let unsubscribe = []
  let found = []
  let pendingPing
  let sequence = 0
  let busy = false
  let disposed = false
  let nextStatusRefresh = 0

  function field(name) {
    return panel.querySelector('[data-field="' + name + '"]')
  }
  function updateStatus() {
    const lobby = api.steam.getLobby()
    const invite = api.steam.getPendingInvite()
    const mode = api.steam.getMode()
    field('mode').textContent = {
      native: 'Native Steamworks',
      'local-debug': 'Local Debug simulation',
      unavailable: 'Steam unavailable',
    }[mode]
    const user = api.steam.getUser()
    field('identity').textContent = user.steamId ? user.name + ' · ' + user.steamId + ' · AppID ' + user.appId : 'No Steam identity'
    field('lobby').textContent = lobby ? lobby.name + ' · ' + lobby.id : 'No lobby'
    field('members').textContent = lobby ? lobby.members.map(id => id === lobby.ownerId ? id + ' (owner)' : id).join(', ') : '—'
    const connected = api.net.isConnected() && api.net.mode() === 'steam-p2p'
    field('transport').textContent = connected
      ? api.net.mode() + ' · ' + api.net.getPeers().length + ' connected · ' + (api.net.isHost() ? 'host' : 'member')
      : 'Disconnected'
    field('metadata').textContent = lobby?.data?.probe ?? '—'
    field('invite').textContent = invite ? invite.lobbyId : 'No pending invite'
    for (const button of panel.querySelectorAll('[data-action]')) {
      const action = button.dataset.action
      const needsNative = ['invite', 'relay', 'stat', 'dlc'].includes(action)
      const needsLobby = ['leave', 'invite', 'metadata'].includes(action)
      button.disabled = busy || (needsNative && mode !== 'native') || (needsLobby && !lobby)
        || (action === 'accept' && !invite) || (action === 'ping' && (!connected || Boolean(pendingPing)))
        || (mode === 'unavailable' && action !== 'init')
    }
  }
  function report(message) {
    if (!disposed) field('result').textContent = message
  }
  async function connectLobby(lobby) {
    if (!lobby) throw new Error('Steam refused the lobby request')
    if (!await api.net.connect({ mode: 'steam-p2p', room: lobby.id })) {
      await api.steam.leaveLobby()
      throw new Error(api.net.getLastError() || 'Could not attach the Steam transport')
    }
    field('lobbyId').value = ''
    report('Joined lobby ' + lobby.id + '. Use Ping peer to verify packet exchange.')
  }
  async function refreshLobbies() {
    found = (await api.steam.listLobbies()).filter(lobby =>
      lobby.data?.example === namespace || lobby.name === lobbyName)
    const select = field('list')
    const selected = select.value
    select.replaceChildren(new Option('Select a lobby', ''))
    for (const lobby of found) {
      select.add(new Option(lobby.name + ' (' + lobby.members.length + '/' + lobby.maxMembers + ') · ' + lobby.id, lobby.id))
    }
    select.value = found.some(lobby => lobby.id === selected) ? selected : (found[0]?.id || '')
    report('Found ' + found.length + ' demo lobbies.')
  }
  const actions = {
    async init() {
      const user = await api.steam.init()
      report(user.steamId ? 'Steam identity ready.' : 'Native: start Steam and check AppID access. Editor: enable Local Debug.')
    },
    async create() {
      await connectLobby(await api.steam.createLobby({ name: lobbyName, maxMembers: 4, data: { example: namespace } }))
    },
    refresh: refreshLobbies,
    async join() {
      const id = field('lobbyId').value.trim() || field('list').value
      if (!id) throw new Error('Select a lobby or enter its ID')
      await connectLobby(await api.steam.joinLobby(id))
    },
    async leave() {
      api.net.disconnect()
      await api.steam.leaveLobby()
      pendingPing = undefined
      field('lobbyId').value = ''
      report('Left the lobby.')
    },
    async invite() {
      report(await api.steam.inviteFriends() ? 'Invite dialog requested.' : 'Steam overlay unavailable.')
    },
    async accept() {
      const invite = api.steam.getPendingInvite()
      if (invite) await connectLobby(await api.steam.joinLobby(invite.lobbyId))
    },
    async relay() {
      report('SDR status: ' + (await api.steam.relayStatus() ?? 'unavailable'))
    },
    async metadata() {
      const updated = await api.steam.setLobbyData('probe', new Date().toISOString())
      report(updated ? 'Lobby metadata updated.' : 'Steam refused metadata update. Try as the owner.')
    },
    ping() {
      const peer = api.net.getPeers().find(peer => peer.id !== api.net.peerId())
      if (!peer) throw new Error('Join from a second client and wait for it to appear in the transport')
      pendingPing = { target: peer.id, token: ++sequence, start: performance.now() }
      api.net.rpc(pingEvent, { token: pendingPing.token }, peer.id)
      report('Ping sent to ' + peer.name + '…')
    },
    async cloudWrite() {
      const value = { savedAt: new Date().toISOString(), user: api.steam.getUser().steamId }
      report(await api.steam.cloudWrite(cloudFile, JSON.stringify(value)) ? 'Cloud probe written.' : 'Cloud write failed.')
    },
    async cloudRead() {
      const value = await api.steam.cloudRead(cloudFile)
      report(value === null ? 'Cloud probe not found.' : 'Cloud probe: ' + value)
    },
    async cloudList() {
      const files = await api.steam.listCloudFiles()
      report('Cloud probe listed: ' + (files.includes(cloudFile) ? 'yes' : 'no') + ' · ' + files.length + ' files total')
    },
    async achievement() {
      const id = field('achievementId').value.trim()
      if (!id) throw new Error('Enter an achievement API name from Steamworks')
      const unlocked = await api.steam.unlockAchievement(id)
      const confirmed = unlocked && await api.steam.queryAchievement(id)
      report(confirmed ? 'Achievement confirmed: ' + id : 'Achievement unavailable: ' + id)
    },
    async stat() {
      const id = field('statId').value.trim()
      if (!id) throw new Error('Enter an integer stat API name from Steamworks')
      const value = await api.steam.readStat(id)
      report(value === null ? 'Stat unavailable.' : id + ' = ' + value)
    },
    async dlc() {
      const id = Number(field('dlcId').value)
      if (!Number.isInteger(id) || id <= 0 || id > 4294967295) throw new Error('Enter a valid DLC AppID')
      report(await api.steam.isDlcInstalled(id) ? 'DLC installed.' : 'DLC not installed or unavailable.')
    },
  }
  return {
    async onStart() {
      panel = api.ui.mount(widget, `
        <article class="mf-steam-lab" aria-label="Steam Relay Lab">
          <header><h1>Steam Relay Lab</h1><strong data-field="mode"></strong></header>
          <p data-field="identity"></p>
          <p class="mf-steam-result" role="status" data-field="result">Initializing Steam…</p>
          <dl>
            <dt>Lobby</dt><dd data-field="lobby"></dd>
            <dt>Members</dt><dd data-field="members"></dd>
            <dt>Transport</dt><dd data-field="transport"></dd>
            <dt>Metadata probe</dt><dd data-field="metadata"></dd>
            <dt>Invite</dt><dd data-field="invite"></dd>
          </dl>
          <section><h2>Lobby &amp; relay</h2>
            <div class="mf-steam-row">
              <button data-action="init">Retry Steam</button><button data-action="create">Create lobby</button>
              <button data-action="refresh">Find lobbies</button><button data-action="leave">Leave</button>
            </div>
            <div class="mf-steam-row">
              <select aria-label="Discovered lobbies" data-field="list"><option value="">Select a lobby</option></select>
              <input aria-label="Lobby ID" data-field="lobbyId" placeholder="Or enter lobby ID" />
              <button data-action="join">Join lobby</button>
            </div>
            <div class="mf-steam-row">
              <button data-action="ping">Ping peer</button><button data-action="relay">Relay status</button>
              <button data-action="invite">Invite friends</button><button data-action="accept">Join invited lobby</button>
              <button data-action="metadata">Update lobby metadata</button>
            </div>
          </section>
          <section><h2>Steam services</h2>
            <div class="mf-steam-row">
              <button data-action="cloudWrite">Cloud write</button><button data-action="cloudRead">Cloud read</button>
              <button data-action="cloudList">Cloud list</button>
            </div>
            <div class="mf-steam-row">
              <input aria-label="Achievement API name" data-field="achievementId" value="ACH_LOBBY_JOINED" />
              <button data-action="achievement">Test achievement</button>
              <input aria-label="Integer stat API name" data-field="statId" placeholder="Integer stat API name" />
              <button data-action="stat">Read stat</button>
              <input aria-label="DLC AppID" data-field="dlcId" placeholder="DLC AppID" />
              <button data-action="dlc">Check DLC</button>
            </div>
          </section>
        </article>`, `
        .mf-steam-lab{pointer-events:auto;position:absolute;inset:16px auto 16px 16px;width:min(680px,calc(100% - 32px));height:fit-content;max-height:calc(100% - 32px);overflow:auto;padding:16px;background:#151b25f5;border:1px solid #3b4b63;border-radius:10px;color:#edf3ff;font:14px/1.4 system-ui,sans-serif}
        .mf-steam-lab header{position:static;display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between}
        .mf-steam-lab h1{font-size:23px;letter-spacing:normal;text-shadow:none}.mf-steam-lab h2{font-size:14px;margin:6px 0}
        .mf-steam-lab header strong{color:#9ae5c3}.mf-steam-lab p{margin:6px 0;text-shadow:none}
        .mf-steam-lab dl{display:grid;grid-template-columns:auto 1fr;gap:4px 8px}.mf-steam-lab dd{margin:0;overflow-wrap:anywhere}
        .mf-steam-lab section{position:static;display:block;padding:8px 0;background:none;text-align:left;border-top:1px solid #3b4b63}
        .mf-steam-row{display:flex;gap:6px;flex-wrap:wrap;margin:5px 0}
        .mf-steam-row button,.mf-steam-row input,.mf-steam-row select{font:inherit;border:1px solid #506078;border-radius:5px;padding:5px 8px;background:#23334a;color:#edf3ff}
        .mf-steam-row button{background:#355b8d;cursor:pointer}.mf-steam-row button:disabled{opacity:.45;cursor:default}
        .mf-steam-row input,.mf-steam-row select{max-width:100%;width:165px}.mf-steam-lab .mf-steam-result{position:sticky;top:0;z-index:1;padding:4px 6px;background:#1d2939;border-radius:4px;overflow-wrap:anywhere;color:#b7e2ff;min-height:1.4em}
      `)
      const onClick = async (event) => {
        const action = event.target.closest?.('button[data-action]')?.dataset.action
        if (!action || busy || !Object.hasOwn(actions, action)) return
        busy = true
        updateStatus()
        try { await actions[action]() }
        catch (error) { report(error instanceof Error ? error.message : String(error)) }
        finally { busy = false; if (!disposed) updateStatus() }
      }
      const onFieldKeyDown = (event) => {
        if (event.target.matches?.('input, select')) event.stopPropagation()
      }
      panel.addEventListener('keydown', onFieldKeyDown)
      panel.addEventListener('click', onClick)
      unsubscribe = [
        () => panel.removeEventListener('keydown', onFieldKeyDown),
        () => panel.removeEventListener('click', onClick),
        api.net.onRpc(pingEvent, (payload, sender) => {
          if (!Number.isSafeInteger(payload?.token)) return
          api.net.rpc(pongEvent, { token: payload.token }, sender)
          report('Received ping from ' + sender + ' and replied.')
        }),
        api.net.onRpc(pongEvent, (payload, sender) => {
          if (sender !== pendingPing?.target || payload?.token !== pendingPing?.token) return
          const ms = Math.round(performance.now() - pendingPing.start)
          pendingPing = undefined
          report('Round trip confirmed · ' + ms + ' ms · ' + sender)
        }),
      ]
      await onClick({ target: panel.querySelector('[data-action="init"]') })
    },
    onUpdate() {
      if (!panel || performance.now() < nextStatusRefresh) return
      nextStatusRefresh = performance.now() + 250
      if (pendingPing && performance.now() - pendingPing.start > 5000) {
        pendingPing = undefined
        report('Ping timed out. Check if the other client is still in the lobby.')
      }
      updateStatus()
    },
    onDestroy() {
      disposed = true
      for (const off of unsubscribe) off()
      api.ui.unmount(widget)
    },
  }
}
